void opeu_process_selected_turn(PARAMETERS) {
  NORMALIZE();
  if (!(SIDE_FLAGS[SIDE] & 0x80)) {
    INITIALIZE_SIDE();
    SIDE_FLAGS[SIDE] |= 0x80;
  }
  if (SCHEDULE & 1)
    DAILY();
  if (SCHEDULE & 2)
    HALF_DAY();
  if (SCHEDULE & 4) {
    HOURLY_A();
    HOURLY_B();
    HOURLY_C();
  }
  PRE_CONTEXT();
  SCHEDULE      = 0;
  NOTIFY        = 0;
  CONTEXT1      = FIND_SIDE(SIDE, 1);
  CONTEXT2      = FIND_SIDE(SIDE, 2);
  CONTEXT3      = FIND_SIDE(SIDE, 3);
  CONTEXT_GROUP = FIND_GROUP(SIDE, GROUP);
  if (UNIT_FLAGS & 4) {
    if (SIDE_STATUS[SIDE] == 1) {
      ACTIVE_BEGIN();
      LABEL();
      if (SIDE_SELECTED(SIDE) == UNIT && SIDE_CONTROL[SIDE] == 1) {
        if (INPUT_MODE ? INPUT_A() : INPUT_B())
          DELAYS[SIDE] = 0;
      }
    }
    if (SIDE_SELECTED(SIDE) == UNIT) {
      SELECTED_BEGIN();
      if (SIDE_CONTROL[SIDE] == 1) {
        if (DELAYS[SIDE] == 0)
          CONTROL_ONE();
      } else
        CONTROL_OTHER();
    }
    if (GROUP_SELECTED(GROUP_PTR) == UNIT)
      GROUP_ACTION();
    if (FINAL_PREDICATE())
      FINAL_ACTION();
  }
}

